def _members(paths):
    """Yield (source path, archive path) in stable traversal order."""
    for src in paths:
        src = os.fspath(src)
        name = os.path.basename(os.path.normpath(src)) or src
        if os.path.isdir(src):
            yield src, name
            for root, dirs, files in os.walk(src):
                dirs.sort()
                files.sort()
                relroot = os.path.relpath(root, os.path.dirname(os.path.normpath(src)) or ".")
                for d in dirs:
                    full = os.path.join(root, d)
                    rel = os.path.relpath(full, os.path.dirname(os.path.normpath(src)) or ".")
                    yield full, rel
                for f in files:
                    full = os.path.join(root, f)
                    rel = os.path.relpath(full, os.path.dirname(os.path.normpath(src)) or ".")
                    yield full, rel
        else:
            yield src, name


